// Reviewer-owned independent probe for GAGAMBA-RC2B-06-B6-ALT-B-SLICE-E-02-P2-Q1.
// Loads the compiled Gagamba.Execution.Linux.M1 assembly and exercises the internal
// DetachedEvidenceVerifier through reflection. Fixtures below were constructed by
// the reviewer from the adopted P0 record (docs/evidence/...frozen-schema-provenance-p0.md
// sections 6, 11.1-11.3, 11.5) and are NOT generated by, nor copied from, the producer
// fixtures. All checks print one line: CHECK|<id>|PASS|FAIL|<detail>.
using System.Reflection;
using System.Reflection.Emit;
using System.Runtime.Loader;
using System.Security.Cryptography;
using System.Text;

const string ValidationNs = "Gagamba.Execution.Linux.M1.Validation";

if (args.Length < 2)
{
    Console.Error.WriteLine("usage: P2Q1Probe <path-to-Debug-M1.dll> <path-to-Release-M1.dll>");
    return 2;
}

var liveContexts = new List<DirLoadContext>();
Assembly LoadIsolated(string path)
{
    var full = Path.GetFullPath(path);
    var context = new DirLoadContext("probe-" + Path.GetFileName(Path.GetDirectoryName(full))!, full);
    liveContexts.Add(context);
    return context.LoadFromAssemblyPath(full);
}

var debugAsm = LoadIsolated(args[0]);
var releaseAsm = LoadIsolated(args[1]);

var total = 0;
var failed = 0;

void Check(string id, string normative, bool ok, string detail)
{
    total++;
    if (!ok) failed++;
    Console.WriteLine($"CHECK|{id}|{(ok ? "PASS" : "FAIL")}|{detail} (normative: {normative})");
}

// ---------- fixture construction (reviewer-owned) ----------
string Rep(string s, int n) => string.Concat(Enumerable.Repeat(s, n));
string Q(string s) => "\"" + s + "\"";
string N(long v) => v.ToString(System.Globalization.CultureInfo.InvariantCulture);
string B(bool v) => v ? "true" : "false";
const string NULL = "null";

string Cjson(SortedDictionary<string, string> fields) =>
    "{" + string.Join(",", fields.Select(kv => $"\"{kv.Key}\":{kv.Value}")) + "}";

byte[] Utf8(string s) => Encoding.UTF8.GetBytes(s);
string ShaHex(byte[] bytes) => Convert.ToHexStringLower(SHA256.HashData(bytes));

