string BuildCatalog(bool usePost)
{
    var f = new SortedDictionary<string, string>(StringComparer.Ordinal)
    {
        ["actionScriptSha256"] = Q(usePost ? post.actionScriptSha256 : pre.actionScriptSha256),
        ["allowRelease"] = B(usePost ? post.allowRelease : pre.allowRelease),
        ["artifactSetSha256"] = Q(usePost ? post.artifactSetSha256 : pre.artifactSetSha256),
        ["caseId"] = Q(usePost ? post.caseId : pre.caseId),
        ["controllerClosureSha256"] = Q(usePost ? post.controllerClosureSha256 : pre.controllerClosureSha256),
        ["driverClosureSha256"] = Q(usePost ? post.driverClosureSha256 : pre.driverClosureSha256),
        ["fixtureManifestSha256"] = Q(usePost ? post.fixtureManifestSha256 : pre.fixtureManifestSha256),
        ["fixturePolicySha256"] = Q(usePost ? post.fixturePolicySha256 : pre.fixturePolicySha256),
        ["hostId"] = Q(usePost ? post.hostId : pre.hostId),
        ["maximumSessionNs"] = N(usePost ? post.maximumSessionNs : pre.maximumSessionNs),
        ["phase"] = Q(usePost ? post.phase : pre.phase),
        ["platformInventorySha256"] = Q(usePost ? post.platformInventorySha256 : pre.platformInventorySha256),
        ["profileId"] = Q(usePost ? post.profileId : pre.profileId),
        ["profileVersion"] = Q(usePost ? post.profileVersion : pre.profileVersion),
        ["qualificationId"] = usePost ? Q(post.qualificationId!) : NULL,
        ["qualificationRecordSha256"] = usePost ? Q(post.qualificationRecordSha256!) : NULL,
        ["rid"] = Q(usePost ? post.rid : pre.rid),
        ["schemaVersion"] = N(1),
        ["scope"] = Q(usePost ? post.scope : pre.scope),
        ["sourceCommit"] = Q(usePost ? post.sourceCommit : pre.sourceCommit),
        ["sourceTree"] = Q(usePost ? post.sourceTree : pre.sourceTree),
        ["topology"] = Q(usePost ? post.topology : pre.topology),
    };
    return Cjson(f);
}

string BuildReview(bool usePost, string hk, string? caseOverride = null, string? phaseOverride = null,
    string? topologyOverride = null, string? hostOverride = null, string? artifactOverride = null,
    string? hmOverride = null, string? hfOverride = null, string? hsOverride = null,
    string? conclusionOverride = null, string? qualIdOverride = null, string? qualRecOverride = null,
    bool qualIdNullOverride = false, bool qualRecNullOverride = false)
{
    var qualId = usePost ? post.qualificationId : null;
    var qualRec = usePost ? post.qualificationRecordSha256 : null;
    if (qualIdOverride is not null) qualId = qualIdOverride;
    if (qualRecOverride is not null) qualRec = qualRecOverride;
    if (qualIdNullOverride) qualId = null;
    if (qualRecNullOverride) qualRec = null;
    var f = new SortedDictionary<string, string>(StringComparer.Ordinal)
    {
        ["actionScriptSha256"] = Q(hsOverride ?? (usePost ? post.actionScriptSha256 : pre.actionScriptSha256)),
        ["artifactSetSha256"] = Q(artifactOverride ?? (usePost ? post.artifactSetSha256 : pre.artifactSetSha256)),
        ["caseId"] = Q(caseOverride ?? (usePost ? post.caseId : pre.caseId)),
        ["catalogSha256"] = Q(hk),
        ["conclusion"] = Q(conclusionOverride ?? "supported-for-bounded-validation"),
        ["fixtureManifestSha256"] = Q(hmOverride ?? (usePost ? post.fixtureManifestSha256 : pre.fixtureManifestSha256)),
        ["fixturePolicySha256"] = Q(hfOverride ?? (usePost ? post.fixturePolicySha256 : pre.fixturePolicySha256)),
        ["hostId"] = Q(hostOverride ?? (usePost ? post.hostId : pre.hostId)),
        ["phase"] = Q(phaseOverride ?? (usePost ? post.phase : pre.phase)),
        ["qualificationId"] = qualId is null ? NULL : Q(qualId),
        ["qualificationRecordSha256"] = qualRec is null ? NULL : Q(qualRec),
        ["schemaVersion"] = N(1),
        ["topology"] = Q(topologyOverride ?? (usePost ? post.topology : pre.topology)),
    };
    return Cjson(f);
}

