string BuildContent(bool usePost, string hk, string hr, string hw, string? caseOverride = null,
    string? phaseOverride = null, string? topologyOverride = null, string? hostOverride = null,
    string? artifactOverride = null, string? hwOverride = null, string? hrOverride = null,
    bool? acceptedOverride = null, string? qualIdOverride = null, string? qualRecOverride = null)
{
    var qualId = usePost ? post.qualificationId : null;
    var qualRec = usePost ? post.qualificationRecordSha256 : null;
