    if (qualRecOverride is not null) qualRec = qualRecOverride;
    var f = new SortedDictionary<string, string>(StringComparer.Ordinal)
    {
        ["accepted"] = B(acceptedOverride ?? true),
        ["artifactSetSha256"] = Q(artifactOverride ?? (usePost ? post.artifactSetSha256 : pre.artifactSetSha256)),
        ["caseId"] = Q(caseOverride ?? (usePost ? post.caseId : pre.caseId)),
