// Build both complete chains with exact digests.
string kPreText = BuildCatalog(false);
string kPostText = BuildCatalog(true);
byte[] kPre = Utf8(kPreText), kPost = Utf8(kPostText);
string hkPre = ShaHex(kPre), hkPost = ShaHex(kPost);

string rPreText = BuildReview(false, hkPre);
string wcPreText = BuildReceipt(false, hkPre, ShaHex(Utf8(rPreText)));
string pPreText = BuildContent(false, hkPre, ShaHex(Utf8(rPreText)), ShaHex(Utf8(wcPreText)));
byte[] rPre = Utf8(rPreText), wcPre = Utf8(wcPreText), pPre = Utf8(pPreText);
string hrPre = ShaHex(rPre), hwPre = ShaHex(wcPre), hpPre = ShaHex(pPre);

string rPostText = BuildReview(true, hkPost);
string wcPostText = BuildReceipt(true, hkPost, ShaHex(Utf8(rPostText)));
string pPostText = BuildContent(true, hkPost, ShaHex(Utf8(rPostText)), ShaHex(Utf8(wcPostText)));
byte[] rPost = Utf8(rPostText), wcPost = Utf8(wcPostText), pPost = Utf8(pPostText);
string hrPost = ShaHex(rPost), hwPost = ShaHex(wcPost), hpPost = ShaHex(pPost);

// ---------- emit reviewer fixture bytes + digests (durable evidence) ----------
if (args.Length >= 3)
{
    var outDir = Path.GetFullPath(args[2]);
    Directory.CreateDirectory(outDir);
    void Emit(string name, string text)
    {
        var bytes = Utf8(text);
        File.WriteAllBytes(Path.Combine(outDir, name), bytes);
        Console.WriteLine($"FIXTURE|{name}|{ShaHex(bytes)}|{bytes.Length}");
    }

    Emit("k-pre.json", kPreText);
    Emit("r-pre.json", rPreText);
    Emit("wc-pre.json", wcPreText);
    Emit("p-pre.json", pPreText);
    Emit("k-post.json", kPostText);
    Emit("r-post.json", rPostText);
    Emit("wc-post.json", wcPostText);
    Emit("p-post.json", pPostText);
    Console.WriteLine($"FIXTURE-DIGEST|Hk-pre|{hkPre}");
    Console.WriteLine($"FIXTURE-DIGEST|Hr-pre|{hrPre}");
    Console.WriteLine($"FIXTURE-DIGEST|Hw-pre|{hwPre}");
    Console.WriteLine($"FIXTURE-DIGEST|Hp-pre|{hpPre}");
    Console.WriteLine($"FIXTURE-DIGEST|Hk-post|{hkPost}");
    Console.WriteLine($"FIXTURE-DIGEST|Hr-post|{hrPost}");
    Console.WriteLine($"FIXTURE-DIGEST|Hw-post|{hwPost}");
    Console.WriteLine($"FIXTURE-DIGEST|Hp-post|{hpPost}");
}

// ---------- reflection plumbing ----------
var verifier = debugAsm.GetType(ValidationNs + ".DetachedEvidenceVerifier", throwOnError: true)!;
var canonicalJson = debugAsm.GetType(ValidationNs + ".CanonicalJson", throwOnError: true)!;
var p2TypeNames = new[]
{
    "DetachedEvidenceVerifier", "ReviewRecordContract", "OwnerReceiptRecordContract",
    "AdminRecordContentContract", "DetachedEvidenceBindingsContract",
};
var p2Types = p2TypeNames.Select(n => debugAsm.GetType(ValidationNs + "." + n, throwOnError: true)!).ToArray();

BindingFlags StNonPub = BindingFlags.Static | BindingFlags.NonPublic;

MethodInfo VMethod(string name) =>
    verifier.GetMethod(name, StNonPub) ?? throw new InvalidOperationException(name);

var mReview = VMethod("TryVerifyReviewRecord");
var mReceipt = VMethod("TryVerifyOwnerReceiptRecord");
var mContent = VMethod("TryVerifyAdminRecordContent");
var mChain = VMethod("TryVerifyDetachedEvidenceChain");
var mHash = canonicalJson.GetMethod("Hash", StNonPub)!;
var mParse = canonicalJson.GetMethod("Parse", StNonPub)!;
var mIsLowerHex = canonicalJson.GetMethod("IsLowerHex", StNonPub)!;

(bool ok, string failure, object? contract, bool escaped, string escape) Call(MethodInfo m, params object?[] inputs)
{
    var args = new object?[inputs.Length + 2];
    for (var i = 0; i < inputs.Length; i++) args[i] = inputs[i];
    try
    {
        var ok = (bool)m.Invoke(null, args)!;
        return (ok, (string)args[^1]!, args[^2], false, string.Empty);
    }
    catch (TargetInvocationException tie)
    {
        var inner = tie.InnerException ?? tie;
        return (false, "!EXC:" + inner.GetType().Name, null, true, inner.GetType().FullName + ": " + inner.Message);
    }
}

(bool ok, string failure, object? contract, bool escaped, string escape) VReview(byte[] r, byte[] k) => Call(mReview, r, k);
(bool ok, string failure, object? contract, bool escaped, string escape) VReceipt(byte[] wc, byte[] k, byte[] r) => Call(mReceipt, wc, k, r);
(bool ok, string failure, object? contract, bool escaped, string escape) VContent(byte[] p, byte[] k, byte[] r, byte[] wc) => Call(mContent, p, k, r, wc);
(bool ok, string failure, object? contract, bool escaped, string escape) VChain(byte[] k, byte[] r, byte[] wc, byte[] p) => Call(mChain, k, r, wc, p);

// ---------- POSITIVE controls ----------
var chainPre = VChain(kPre, rPre, wcPre, pPre);
Check("POS-01", "P0 11.1-11.3, 11.5: full reviewer-built B2/pre chain verifies", chainPre.ok && chainPre.failure.Length == 0 && chainPre.contract is not null,
    $"ok={chainPre.ok} failure='{chainPre.failure}'");
var chainPost = VChain(kPost, rPost, wcPost, pPost);
Check("POS-02", "P0 11.1-11.3, 11.5: full reviewer-built B3/post chain verifies", chainPost.ok && chainPost.failure.Length == 0 && chainPost.contract is not null,
    $"ok={chainPost.ok} failure='{chainPost.failure}'");
var revPre = VReview(rPre, kPre);
var recPre = VReceipt(wcPre, kPre, rPre);
var conPre = VContent(pPre, kPre, rPre, wcPre);
Check("POS-03", "owner decision 14-15: individual entries accept every valid record",
    revPre.ok && recPre.ok && conPre.ok,
    $"review={revPre.ok} receipt={recPre.ok} content={conPre.ok}");

if (chainPre.contract is not null)
{
    var t = chainPre.contract.GetType();
    string Get(object o, string p) => (string)t.GetProperty(p)!.GetValue(o)!;
    Check("POS-04", "P0 11.5: Hk/Hr/Hw/Hp returned by the chain equal reviewer-computed digests",
        Get(chainPre.contract, "Hk") == hkPre && Get(chainPre.contract, "Hr") == hrPre &&
        Get(chainPre.contract, "Hw") == hwPre && Get(chainPre.contract, "Hp") == hpPre,
        $"Hk={Get(chainPre.contract, "Hk")[..8]}.. Hr={Get(chainPre.contract, "Hr")[..8]}.. Hw={Get(chainPre.contract, "Hw")[..8]}.. Hp={Get(chainPre.contract, "Hp")[..8]}..");
}

// Codec.Hash must equal platform SHA-256 over the exact bytes (no reserialization).
var codecHashPre = (string)mHash.Invoke(null, new object?[] { rPre })!;
Check("POS-05", "P0 6.11: codec hash equals platform SHA-256 over exact received R bytes",
    codecHashPre == ShaHex(rPre) && codecHashPre == hrPre,
    $"codec={codecHashPre[..16]}.. platform={ShaHex(rPre)[..16]}..");

// Cross-check: reviewer-constructed field order equals the pinned expected arrays.
string[] PinnedArray(string field) => (string[])verifier.GetField(field, StNonPub)!.GetValue(null)!;
string[] KeysOf(string text) => System.Text.Json.JsonDocument.Parse(text).RootElement.EnumerateObject().Select(property => property.Name).ToArray();
Check("POS-06a", "P0 11.1: reviewer R field order equals implementation's pinned ReviewFields",
    KeysOf(rPreText).SequenceEqual(PinnedArray("ReviewFields")),
    string.Join(",", KeysOf(rPreText)));
Check("POS-06b", "P0 11.2: reviewer Wc field order equals implementation's pinned ReceiptFields",
    KeysOf(wcPreText).SequenceEqual(PinnedArray("ReceiptFields")),
    string.Join(",", KeysOf(wcPreText)));
Check("POS-06c", "P0 11.3: reviewer P field order equals implementation's pinned AdminContentFields",
    KeysOf(pPreText).SequenceEqual(PinnedArray("AdminContentFields")),
    string.Join(",", KeysOf(pPreText)));

// K structural refusals via the reused P1 entry (pre/post pair rules).
var preWithQual = Utf8(BuildCatalog(false).Replace("\"qualificationId\":null", "\"qualificationId\":\"x\"").Replace("\"qualificationRecordSha256\":null", "\"qualificationRecordSha256\":\"" + Rep("e", 64) + "\""));
var kvBad = VReview(rPre, preWithQual);
Check("POS-07", "P0 7.1: pre-phase K with a non-null qualification pair is refused by reused P1 verification",
    !kvBad.ok && kvBad.failure == "K pre qualificationId",
    $"failure='{kvBad.failure}'");

// ---------- MALFORMED CJSON-1 controls ----------
void Malformed(string id, string normative, byte[] input, string expected)
{
    var result = VReview(input, kPre);
    Check(id, normative, !result.ok && !result.escaped && result.failure == expected,
        $"expected='{expected}' actual='{result.failure}' escaped={result.escaped}");
}

Malformed("MAL-01", "P0 6.8 round-trip", Utf8(rPreText + " "), "noncanonical CJSON-1 representation");
Malformed("MAL-02", "P0 6.1 ASCII only", Utf8(rPreText + "\n"), "CJSON-1 ASCII printable bytes");
Malformed("MAL-03", "P0 6.2/6.3 no duplicate keys / ascending", Utf8(rPreText.Replace("\"caseId\":\"" + pre.caseId + "\",", "\"caseId\":\"" + pre.caseId + "\",\"caseId\":\"" + pre.caseId + "\",")), "CJSON-1 keys are not strictly ascending");
Malformed("MAL-04", "P0 6.3 ascending keys", Utf8(rPreText.Replace("\"caseId\":\"" + pre.caseId + "\",\"catalogSha256\":\"" + hkPre + "\",", "\"catalogSha256\":\"" + hkPre + "\",\"caseId\":\"" + pre.caseId + "\",")), "CJSON-1 keys are not strictly ascending");
Malformed("MAL-05", "P0 6.4/6.8 escapes are literal-form only", Utf8(rPreText.Replace("\"caseId\":\"" + pre.caseId + "\"", "\"caseId\":\"review\\u002dcase-alpha-01\"")), "noncanonical CJSON-1 representation");
Malformed("MAL-06", "P0 6.5 integer form", Utf8(rPreText.Replace("\"schemaVersion\":1", "\"schemaVersion\":1.0")), "CJSON-1 unsigned canonical integer");
Malformed("MAL-07", "P0 6.9 empty strings", Utf8(rPreText.Replace("\"caseId\":\"" + pre.caseId + "\"", "\"caseId\":\"\"")), "CJSON-1 string");
Malformed("MAL-08", "P0 6.4 unsupported escape", Utf8(rPreText.Replace("\"caseId\":\"" + pre.caseId + "\"", "\"caseId\":\"review\\qcase\"")), "invalid CJSON-1");
Malformed("MAL-09", "P0 6.2 exactly one object", Utf8(rPreText + "{}"), "invalid CJSON-1");
var truncated = (byte[])rPre.Clone(); truncated = truncated[..^1];
Malformed("MAL-10", "P0 6.2 truncation", truncated, "invalid CJSON-1");
var nonAscii = (byte[])rPre.Clone(); nonAscii[10] = 0xE9;
Malformed("MAL-11", "P0 6.1 ASCII only", nonAscii, "CJSON-1 ASCII printable bytes");
Malformed("MAL-12", "P0 6.10 size limit", Utf8(rPreText + new string('x', 70_000)), "CJSON-1 size");
Malformed("MAL-13", "P0 6.10 size limit", [], "CJSON-1 size");
Malformed("MAL-14", "P0 6.12 lower-case hex", Utf8(rPreText.Replace(pre.hostId, pre.hostId.ToUpperInvariant())), "hostId hex");
Malformed("MAL-15", "P0 11.1 schemaVersion=1 integer", Utf8(rPreText.Replace("\"schemaVersion\":1", "\"schemaVersion\":\"1\"")), "schemaVersion integer");
Malformed("MAL-16", "P0 11.1 exact field set: missing field", Utf8(rPreText.Replace("\"conclusion\":\"supported-for-bounded-validation\",", "")), "R field set");
Malformed("MAL-17", "P0 11.1 exact field set: extension after an ascending key", Utf8(rPreText.Replace("\"hostId\":\"" + pre.hostId + "\",", "\"hostId\":\"" + pre.hostId + "\",\"hostNote\":1,")), "R field set");
Malformed("MAL-18", "P0 11.1 exact field set: extension before all keys", Utf8("{\"aaa\":1," + rPreText[1..]), "R field set");
var deep = Utf8(rPreText.Replace("\"hostId\":\"" + pre.hostId + "\",", "\"hostId\":\"" + pre.hostId + "\",\"zdeep\":{\"a\":{\"b\":{\"c\":{\"d\":{\"e\":{\"f\":{\"g\":{\"h\":{\"i\":1}}}}}}}}}},"));
var deepResult = VReview(deep, kPre);
Check("MAL-19", "P1-Q1-F01 depth-8 implementation bound (accepted limitation, not a CJSON-1 rule)",
    !deepResult.ok && !deepResult.escaped && (deepResult.failure == "invalid CJSON-1" || deepResult.failure == "CJSON-1 depth" || deepResult.failure == "R field set"),
    $"failure='{deepResult.failure}' escaped={deepResult.escaped}");

var pAcceptedString = Utf8(pPreText.Replace("\"accepted\":true", "\"accepted\":\"true\""));
var pStrResult = VContent(pAcceptedString, kPre, rPre, wcPre);
Check("MAL-20", "P0 11.3 accepted true boolean", !pStrResult.ok && pStrResult.failure == "accepted boolean",
    $"failure='{pStrResult.failure}'");
var pAcceptedFalse = Utf8(pPreText.Replace("\"accepted\":true", "\"accepted\":false"));
var pFalseResult = VContent(pAcceptedFalse, kPre, rPre, wcPre);
Check("MAL-21", "P0 11.3 accepted = true literal", !pFalseResult.ok && pFalseResult.failure == "P accepted is not true",
    $"failure='{pFalseResult.failure}'");

// ---------- hash-consistent semantic-invalidity controls ----------
// Downstream propagation helpers keep every content identity correct so the
// refusal is proven to be the named semantic relationship, not a stale hash.
(byte[] r, byte[] wc, byte[] p) WithEditedReview(string rText)
{
    var hr = ShaHex(Utf8(rText));
    var wcText = BuildReceipt(false, hkPre, hr);
    var hw = ShaHex(Utf8(wcText));
    var pText = BuildContent(false, hkPre, hr, hw);
    return (Utf8(rText), Utf8(wcText), Utf8(pText));
}

(byte[] r, byte[] wc, byte[] p) WithEditedReceipt(string wcText)
{
    var hw = ShaHex(Utf8(wcText));
    var pText = BuildContent(false, hkPre, hrPre, hw);
    return (rPre, Utf8(wcText), Utf8(pText));
}

