// ---------- IL scanning (reviewer implementation) ----------
var opcodesByValue = typeof(OpCodes).GetFields(BindingFlags.Public | BindingFlags.Static)
    .Where(f => f.FieldType == typeof(OpCode)).Select(f => (OpCode)f.GetValue(null)!)
    .ToDictionary(op => unchecked((ushort)op.Value));

IEnumerable<(byte Kind, long Operand)> Operands(byte[] il)
{
    var pos = 0;
    while (pos < il.Length)
    {
        ushort key = il[pos++];
        if (key == 0xfe) { if (pos >= il.Length) yield break; key = (ushort)(0xfe00 | il[pos++]); }
        if (!opcodesByValue.TryGetValue(key, out var op)) yield break;
        long operand = 0;
        switch (op.OperandType)
        {
            case OperandType.InlineNone: break;
            case OperandType.ShortInlineBrTarget or OperandType.ShortInlineI or OperandType.ShortInlineVar:
                operand = il[pos]; pos += 1; break;
            case OperandType.InlineVar:
                operand = BitConverter.ToUInt16(il, pos); pos += 2; break;
            case OperandType.InlineBrTarget or OperandType.InlineField or OperandType.InlineMethod
                or OperandType.InlineSig or OperandType.InlineString or OperandType.InlineTok
                or OperandType.InlineType or OperandType.InlineI:
                operand = BitConverter.ToInt32(il, pos); pos += 4; break;
            case OperandType.ShortInlineR:
                operand = BitConverter.ToInt32(il, pos); pos += 4; break;
            case OperandType.InlineI8 or OperandType.InlineR:
                operand = BitConverter.ToInt64(il, pos); pos += 8; break;
            case OperandType.InlineSwitch:
                var count = BitConverter.ToInt32(il, pos); pos += 4 + count * 4; break;
            default:
                yield break;
        }
        var kind = op.OperandType switch
        {
            OperandType.InlineMethod => (byte)1,
            OperandType.InlineField => (byte)2,
            OperandType.InlineType => (byte)3,
            OperandType.InlineTok => (byte)4,
            OperandType.InlineString => (byte)5,
            _ => (byte)0,
        };
        yield return (kind, operand);
    }
}

IEnumerable<MethodBase> MembersOf(Type t) =>
    t.GetMethods(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance | BindingFlags.Static | BindingFlags.DeclaredOnly)
        .Cast<MethodBase>().Concat(t.GetConstructors(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance | BindingFlags.Static | BindingFlags.DeclaredOnly));

Type[] SafeTypes(Assembly asm)
{
    try { return asm.GetTypes(); }
    catch (ReflectionTypeLoadException ex) { return ex.Types.Where(t => t is not null).Cast<Type>().ToArray(); }
}

// Positive control for my scanner: TryVerifyDetachedEvidenceChain must reference VerifyReviewRecord.
var chainBody = mChain.GetMethodBody()!.GetILAsByteArray()!;
var verifyReview = verifier.GetMethod("VerifyReviewRecord", StNonPub)!;
var posControl = Operands(chainBody).Any(o => o.Kind == 1 && o.Operand == verifyReview.MetadataToken);
Check("REACH-01", "reviewer scanner positive control: known intra-core call token detected", posControl,
    $"token=0x{verifyReview.MetadataToken:x8}");

void ScanAssembly(Assembly asm, string label)
{
    var types = SafeTypes(asm);
    var p2 = types.Where(t => p2TypeNames.Contains(t.Name) && t.Namespace == ValidationNs).ToArray();
    var targetTokens = p2.SelectMany(MembersOf).Select(m => m.MetadataToken).ToHashSet();
    var p2TypesSet = p2.Select(t => t.FullName!).ToHashSet();
    var methodOffenders = new List<string>();
    var typeOffenders = new List<string>();
    var stringOffenders = new List<string>();
    foreach (var t in types.Where(t => t.Namespace != ValidationNs))
    {
        foreach (var m in MembersOf(t))
        {
            var body = m.GetMethodBody();
            if (body is null) continue;
            foreach (var (kind, operand) in Operands(body.GetILAsByteArray() ?? []))
            {
                if (kind == 1 && targetTokens.Contains((int)operand))
                    methodOffenders.Add($"{t.FullName}.{m.Name} token=0x{(int)operand:x8}");
                if (kind is 3 or 4)
                {
                    try
                    {
                        var resolved = m.Module.ResolveMember((int)operand);
                        if (resolved?.DeclaringType is { } dt && p2TypesSet.Contains(dt.FullName ?? ""))
                            typeOffenders.Add($"{t.FullName}.{m.Name} type={dt.FullName}");
                    }
                    catch { }
                }
                if (kind == 5)
                {
                    try
                    {
                        var text = m.Module.ResolveString((int)operand);
                        if (text.Contains("DetachedEvidence", StringComparison.Ordinal))
                            stringOffenders.Add($"{t.FullName}.{m.Name} string='{text}'");
                    }
                    catch { }
                }
            }
        }
    }
    Check($"REACH-{label}-01", "owner 20: zero production direct-callers of P2 members (Debug/Release)", methodOffenders.Count == 0,
        $"{p2.Length} P2 types, {targetTokens.Count} tokens, offenders={methodOffenders.Count}" + (methodOffenders.Count > 0 ? " :: " + string.Join(";", methodOffenders.Take(5)) : ""));
    Check($"REACH-{label}-02", "owner 20 (reviewer-added): zero production type-token references to P2 types", typeOffenders.Count == 0,
        $"offenders={typeOffenders.Count}" + (typeOffenders.Count > 0 ? " :: " + string.Join(";", typeOffenders.Take(5)) : ""));
    Check($"REACH-{label}-03", "owner 20 (reviewer-added): zero production string literals naming DetachedEvidence (reflection-name probe)", stringOffenders.Count == 0,
        $"offenders={stringOffenders.Count}" + (stringOffenders.Count > 0 ? " :: " + string.Join(";", stringOffenders.Take(5)) : ""));
    Check($"REACH-{label}-04", "owner 20: no Validation-namespace type is exported", !asm.GetExportedTypes().Any(t => t.Namespace == ValidationNs),
        $"{asm.GetName().Name}");
    var p2AllInternal = p2.All(t => !t.IsPublic && !t.IsNestedPublic);
    Check($"REACH-{label}-05", "owner 20: P2 types are present and internal in the scanned assembly", p2.Length == 5 && p2AllInternal,
        $"present={p2.Length} internal={p2AllInternal}");
    var detachedSet = p2.ToHashSet();
    var sigOffenders = new List<string>();
    foreach (var t in types.Where(t => t.Namespace != ValidationNs))
        foreach (var m in t.GetMembers(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance | BindingFlags.Static | BindingFlags.DeclaredOnly))
        {
            var referenced = m switch
            {
                MethodInfo mi => mi.GetParameters().Select(p => p.ParameterType).Prepend(mi.ReturnType),
                ConstructorInfo ci => ci.GetParameters().Select(p => p.ParameterType),
                FieldInfo fi => new[] { fi.FieldType },
                PropertyInfo pi => new[] { pi.PropertyType },
                _ => Enumerable.Empty<Type>(),
            };
            if (referenced.Any(r => detachedSet.Contains(r))) sigOffenders.Add($"{t.FullName}.{m.Name}");
        }
    Check($"REACH-{label}-06", "owner 20: no production signature consumes a P2 result type", sigOffenders.Count == 0,
        $"offenders={sigOffenders.Count}");
}

