    {
        var body = m.GetMethodBody();
        if (body is null) continue;
        foreach (var (kind, operand) in Operands(body.GetILAsByteArray() ?? []))
        {
            if (kind is not (1 or 4)) continue;
            MethodBase? resolved;
            try { resolved = m.Module.ResolveMethod((int)operand); } catch { continue; }
            if (resolved?.DeclaringType is not { } dt || dt.Namespace != ValidationNs) continue;
            var name = resolved.Name;
            var owner = dt.Name;
            if (p2TypeNames.Contains(owner)) { callTargets.Add(owner + "." + name); continue; }
            if (dt.IsNested && dt.DeclaringType is { } outerType && p2TypeNames.Contains(outerType.Name))
            {
                // Compiler-generated nested types (lambdas, record helpers) belong to their P2 declaring type.
                callTargets.Add(outerType.Name + "<generated>." + name);
                continue;
            }
            if (owner == "CatalogContract" && name.StartsWith("get_", StringComparison.Ordinal)) { callTargets.Add(owner + "." + name); continue; }
            var surface = owner + "." + name;
            callTargets.Add(surface);
            if (!allowedSurfaces.Contains(surface)) unexpected.Add($"{t.Name}.{m.Name} -> {surface}");
        }
    }
}
Check("P1R-01", "owner 13: P2 call targets are limited to itself, CatalogContract reads, and the authorized P1 surface",
    unexpected.Count == 0, unexpected.Count == 0 ? "clean" : string.Join(";", unexpected));
Console.WriteLine("P1R-SURFACE|" + string.Join(", ", callTargets));

// ---------- summary ----------
Console.WriteLine($"SUMMARY|total={total}|failed={failed}");
return failed == 0 ? 0 : 1;

sealed class DirLoadContext : System.Runtime.Loader.AssemblyLoadContext
{
    private readonly AssemblyDependencyResolver resolver;
    private readonly string dir;

    public DirLoadContext(string name, string componentPath) : base(name)
    {
        resolver = new AssemblyDependencyResolver(componentPath);
        dir = Path.GetDirectoryName(componentPath)!;
    }

    protected override Assembly? Load(AssemblyName assemblyName)
    {
        var resolved = resolver.ResolveAssemblyToPath(assemblyName);
        if (resolved is not null) return LoadFromAssemblyPath(resolved);
        var candidate = Path.Combine(dir, assemblyName.Name + ".dll");
        return File.Exists(candidate) ? LoadFromAssemblyPath(candidate) : null;
    }
}
